        pm.expect(jsonData.products).to.be.an('array').and.not.empty;
        pm.expect(jsonData).to.have.property('total');
        pm.expect(jsonData).to.have.property('totalProducts');
        pm.expect(jsonData).to.have.property('totalQuantity');

        // Verificar que los campos extras NO se reflejan en la respuesta
        pm.expect(jsonData).to.not.have.property('campoExtra');
        pm.expect(jsonData).to.not.have.property('descuento');
    } else if (code === 400) {
        // Escenario 2: El servidor rechaza la solicitud por campos no permitidos
        pm.expect(jsonData).to.have.property('message');
    } else {
        pm.expect.fail('Código HTTP inesperado: ' + code + '. Se esperaba 200, 201 o 400.');
    }
});

